  const github = {rest: {issues: {
    listComments: async () => ({data: comments}),
    createComment: async args => {writes.push(['create', args]); const id = 80 + writes.length;
      comments.push({id, user: {login: 'github-actions[bot]'}, body: args.body}); return {data: {id, html_url: `https://github.com/example/product/pull/5#issuecomment-${id}`}};},
    updateComment: async args => {writes.push(['update', args]); const item = comments.find(entry => entry.id === args.comment_id); if (item) item.body = args.body;},
  }}, paginate: async (method, args) => (await method(args)).data};
  const context = {repo: {owner: 'example', repo: 'product'}, runId: 42};
  const held = {number: 5, head_sha: 'a'.repeat(40), cause: 'receipt_protected_controls', reason: 'The exact-head owner confirmation is missing.'};
  await post({github, context, assessment: held});
  // The owner confirmed, and the next run is held for another reason: a new comment, not an edit nobody is told about.
  await post({github, context, assessment: {...held, cause: 'receipt_history_changed', reason: 'The findings changed.'}});
  assert.deepEqual(writes.map(([kind]) => kind), ['create', 'create', 'update']);
  assert.match(writes[1][1].body, /\*\*Cause:\*\* `receipt_history_changed`/);
  assert.equal(writes[2][1].comment_id, 81);
  assert.match(writes[2][1].body, /^Superseded: .*issuecomment-82\).*cause changed\.$/);
  assert.ok(!writes[2][1].body.includes(MARKER), 'the superseded notice is no longer found as the current one');
  // The same cause again: the current notice is updated in place.
  await post({github, context, assessment: {...held, cause: 'receipt_history_changed', reason: 'Still changed.'}});
  assert.deepEqual(writes.slice(3).map(([kind, args]) => [kind, args.comment_id]), [['update', 82]]);
  // An earlier notice that names no cause (an older engine's) is a different cause too.
  comments.push({id: 90, user: {login: 'github-actions[bot]'}, body: `${MARKER}\n## Clouseau review incomplete\n\nNo cause line.`});
  await post({github, context, assessment: {...held, cause: 'receipt_history_changed', reason: 'Changed again.'}});
  assert.deepEqual(writes.slice(4).map(([kind, args]) => [kind, args.comment_id ?? null]), [['create', null], ['update', 90]]);
  // The history-changed steps name what resolves it, never a local re-review.
  const text = body({...held, cause: 'receipt_history_changed'}, 'https://github.com/example/product/actions/runs/42');
  assert.match(text, /Remove the `clouseau-local-review` marker/);
  assert.doesNotMatch(text, /Run the local review again/);
});

test('an annotation is raised only for an incomplete review', () => {
  const warnings = [];
  const core = {warning: line => warnings.push(line)};
  annotate({core, assessment: {decision: 'auto_approve'}});
  annotate({core, assessment: {decision: 'review_incomplete', cause: 'provider_key_invalid', reason: 'KEY problem'}});
  annotate({core, assessment: {decision: 'review_incomplete', reason: 'no cause'}});
  assert.deepEqual(warnings, ['Clouseau review incomplete (provider_key_invalid): KEY problem',
    'Clouseau review incomplete (evidence_incomplete): no cause']);
});

test('classification names the unreadable file, and shows validation detail only when it is a plain constant', () => {
  assert.match(classify(Object.assign(new Error('x'), {unavailable: true})).reason, /Changed file unknown cannot be read/);
  assert.match(classify(Object.assign(new Error('x'), {unavailable: true, path: 'src/a.ts'})).reason, /Changed file src\/a\.ts cannot/);
  assert.equal(classify(new Error('Invalid acceptance evidence: factor value')).reason.endsWith('attempts: factor value.'), true);
  const named = classify(new Error('Invalid acceptance evidence: changed source cannot be excluded: src/a_b.py has content, so mark it inspected and cite a quote from it'));
  assert.equal(named.cause, 'review_output_invalid');
  assert.match(named.reason, /attempts: changed source cannot be excluded: src\/a_b\.py has content, so mark it inspected and cite a quote from it\.$/);
  assert.equal(classify(new Error('Invalid acceptance evidence: <script>alert(1)</script> $secret')).reason.endsWith('3 consecutive attempts.'), true);
});

